def find_orfs(s):
    """Return list of orfs: (start_pos_0based, len_nt, frame, mid_frame, orf_seq)"""
    orfs=[]
    n=len(s)
    for frame in range(3):
        i=frame
        last_stop = None
        # find first stop in each frame, then work backward
        # simpler: scan for start...stop
        while i < n-2:
            codon = s[i:i+3]
            if codon in {"ATG"}:
                # extend to next stop in this frame
                j=i
                while j+2 < n:
                    c2 = s[j:j+3]
                    if c2 in stops:
                        orfs.append((i, j+3-i, frame+1, (i%3)+1, s[i:j+3]))
                        break
                    j+=3
                else:
                    orfs.append((i, n-i, frame+1, (i%3)+1, s[i:n]))
                i = j+3 if j+2<n else n
            else:
                i+=3
    return orfs

def get_orfs(s, minlen=60):
    """protein-annotated ORF finding using 'last stop' approach: ORFs start at any ATG with no in-frame stop before"""
    results=[]
    n=len(s)
    stops = {"TAA","TAG","TGA"}
    for frame in range(3):
        # collect all stop positions in this frame
        stops_pos=[]
        i=frame
        while i+2 < n:
            if s[i:i+3] in stops:
                stops_pos.append(i)
            i+=3
        # collect all ATG positions
        atgs=[]
        i=frame
        while i+2 < n:
            if s[i:i+3]=="ATG":
                atgs.append(i)
            i+=3
        # for each atg, find next stop
        for atg in atgs:
            nxt=[sp for sp in stops_pos if sp>atg]
            if nxt:
                end=nxt[0]+3
            else:
                end=n
            length=end-atg
            if length>=minlen:
                inner_starts=[a for a in atgs if atg<a<end]
                results.append({
                    "start": atg, "end": end, "len": length, "frame": frame+1,
                    "dna": s[atg:end], "bounded_by_stop": (end<n),
                    "atgs_inside": len(inner_starts)
                })
    return results

